import {accountPlayer,privateNotice} from './hotseat.js';
import {RULES} from './rules-config.js';
import {CARDS,VEHICLES} from './content.js';
import {art,vehicleImage} from './illustrations.js';
import {portrait} from './portraits.js';
const fmt=n=>Math.round(n).toLocaleString('zh-CN');
export function shopInfo(g){
 const p=accountPlayer(g);if(!p)return {p:null,reason:'等待真人接手',vehicles:[],cards:[],remaining:0,space:0};const reason=!p.alive?'你已退出本局':g.s.phase==='finished'?'本局旅行已结束':g.player.id!==p.id?'电脑回合，先浏览你的补给清单':!g.canShop()?'停在地图上的补给商店后才能购买':'';
 const vehicles=VEHICLES.slice(1).map(v=>{const owned=p.vehicle>=v.id,why=owned?(p.vehicle===v.id?'当前装备':'已拥有更高等级工具'):reason|| (p.money<v.price?'现金不足，还差 '+fmt(v.price-p.money):'');return {...v,owned,cashAfter:p.money-v.price,reason:why,allowed:!why};});
 const cards=Object.entries(CARDS).filter(([key])=>g.s.mode.allowedCards.includes(key)).map(([key,c])=>{const price=g.cardPrice(key,p),count=p.cards.filter(k=>k===key).length,why=reason||(p.cards.length>=RULES.handLimit?'卡包已满，先用掉一些卡片':p.shopUsed>=2?'本回合已购卡 2 张':p.tickets<price?'点券不足，还差 '+fmt(price-p.tickets):'');return {key,...c,price,count,ticketsAfter:p.tickets-price,reason:why,allowed:!why};});
 return {p,reason,vehicles,cards,remaining:Math.max(0,2-p.shopUsed),space:RULES.handLimit-p.cards.length};
}
export function shopPanel(g){const q=shopInfo(g),p=q.p;if(!p)return privateNotice();const c=g.char(p);
 return `<div class="shop-wallet"><span>${portrait(c.id)}</span><div><strong>${c.name}的补给清单</strong><small>当前出行 · ${VEHICLES[p.vehicle].name}</small></div></div><div class="shop-counters"><div><small>奶币 · 购买交通工具</small><b>${fmt(p.money)}</b></div><div><small>点券 · 购买道具卡</small><b>${p.tickets}<span> / 150</span></b></div></div><p class="shop-status">${q.reason||'欢迎到店，选好下一次出发的装备。'}</p><h3>出行工具</h3><p class="shop-explain">升级需全额支付，原工具不折价。购入后默认使用新工具的骰子上限，下次掷骰前可以自行调小。</p><div class="shop-vehicles">${q.vehicles.map(v=>`<article class="shop-tool" data-shop-vehicle="${v.id}">${vehicleImage(v.id)}<h4>${v.name}</h4><span class="badge">可选 1—${v.dice} 颗骰子</span><div class="shop-tool-price"><b>${fmt(v.price)}</b> 奶币</div><p>加油站交通附加费 +${v.id*60}；另计基础费与实际步数。</p><small>${v.owned?v.reason:v.cashAfter<0?'现金缺口 '+fmt(-v.cashAfter):'购买后现金 '+fmt(v.cashAfter)}</small>${v.reason&&!v.owned?`<p class="shop-item-reason">${v.reason}</p>`:''}<button class="${v.allowed?'primary':'secondary'}" data-act="vehicle" data-id="${v.id}" ${v.allowed?'':'disabled'}>${v.owned?v.reason:'购入'+v.name}</button></article>`).join('')}</div><div class="shop-card-heading"><h3>奶伴道具卡</h3><span>卡包 ${p.cards.length}/${RULES.handLimit} · 本回合还可购 ${q.remaining} 张</span></div><p class="shop-explain">拾取地图点券 +10，经过起点 +25，停靠补给站 +30。点券不计入净资产；每回合最多购卡两张，购买工具不占购卡次数。</p><div class="shop-cards">${q.cards.map(c=>`<article class="shop-card ${c.allowed?'':'unavailable'}" data-shop-card="${c.key}"><div class="shop-card-top"><span class="badge">${c.price} 点券</span><small>已有 ${c.count} 张</small></div>${art(c.key)}<h4>${c.name}</h4><p>${c.description}</p><div class="shop-card-budget">${c.ticketsAfter<0?'点券缺口 '+fmt(-c.ticketsAfter):'购后点券 '+fmt(c.ticketsAfter)}</div><p class="shop-item-reason">${c.reason||'现在可购买'}</p><button class="${c.allowed?'primary':'secondary'}" data-act="shop" data-key="${c.key}" ${c.allowed?'':'disabled'}>放进卡包</button></article>`).join('')}</div>`;
}
